def _mapped_ethercat_hand_sides(args: argparse.Namespace) -> list[str]:
    map_spec = resolve_action_map(args.action_map_preset, args.action_map)
    rules = parse_named_action_map(map_spec)
    mapped_keys = get_mapped_keys(rules)
    eth_sides: list[str] = []
    if "hand_left" in mapped_keys and args.hand_eth_left:
        eth_sides.append(f"left={args.hand_eth_left}")
    if "hand_right" in mapped_keys and args.hand_eth_right:
        eth_sides.append(f"right={args.hand_eth_right}")
    return eth_sides


def _maybe_reexec_with_sudo_for_ethercat(args: argparse.Namespace) -> None:
    if args.not_use_hardware:
        return
    if not hasattr(os, "geteuid") or os.geteuid() == 0:
        return
    eth_sides = _mapped_ethercat_hand_sides(args)
    if not eth_sides:
        return

    print(
        "[sudo] EtherCAT XHand requires root; re-running with sudo -E "
        f"for {', '.join(eth_sides)}"
    )
    subprocess.run(["sudo", "-v"], check=True)
    os.execvp("sudo", ["sudo", "-E", sys.executable, *sys.argv])


def _state_log_from_position(
    position: np.ndarray,
    hand_left: np.ndarray | None = None,
    hand_right: np.ndarray | None = None,
) -> dict:
    position = np.asarray(position, dtype=float).reshape(-1)
    state = {
        "q_torso": position[4:10],
        "q_right": position[10:17],
        "q_left": position[17:24],
        "q_head": position[24:26],
    }
    if hand_right is not None:
        state["q_right_hand"] = np.asarray(hand_right, dtype=float).reshape(-1)
    if hand_left is not None:
        state["q_left_hand"] = np.asarray(hand_left, dtype=float).reshape(-1)
    return state


def _state_log_from_controller(controller: RBY1WithXHandMuJoCoController) -> dict:
    state = {
        "q_torso": np.asarray(controller.q_current_torso, dtype=float),
        "q_right": np.asarray(controller.q_current_right, dtype=float),
        "q_left": np.asarray(controller.q_current_left, dtype=float),
        "q_head": np.asarray(controller.q_current_head, dtype=float),
    }
    if hasattr(controller, "q_current_right_hand"):
        state["q_right_hand"] = np.asarray(controller.q_current_right_hand, dtype=float)
    if hasattr(controller, "q_current_left_hand"):
        state["q_left_hand"] = np.asarray(controller.q_current_left_hand, dtype=float)
    return state


