def _save_rollout_experiment_log(
    experiment_log: list[dict],
    args: argparse.Namespace,
    recording_path: str | None,
) -> None:
    if not args.experiment_recording:
        return
    if recording_path is not None:
        output_path = os.path.join(recording_path, f"{args.experiment_recording_name}.npy")
    else:
        output_path = "References/recordings/policy_real_recording.npy"
    out_dir = os.path.dirname(os.path.abspath(output_path))
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
    try:
        np.save(output_path, np.asarray(experiment_log, dtype=object))
        print(
            f"[recording] Saved experiment data (n={len(experiment_log)}) "
            f"to {os.path.abspath(output_path)}"
        )
    except Exception as e:
        print(f"[recording] Failed to save experiment data: {e}")


