def _warn_if_not_foreground_process() -> None:
    try:
        tty_fg_pgid = os.tcgetpgrp(sys.stdin.fileno())
        own_pgid = os.getpgrp()
    except Exception:
        return
    if tty_fg_pgid != own_pgid:
        print(
            "[process][WARNING] This rollout is not the foreground process group for "
            f"the terminal (own pgid={own_pgid}, tty fg pgid={tty_fg_pgid}). "
            "Ctrl+C in that terminal will not reach this process; use SIGTERM/SIGINT "
            "or stop the owning job/process group.",
            flush=True,
        )


def _acquire_single_rollout_lock(args: argparse.Namespace):
    if args.not_use_hardware or args.allow_concurrent_rollout:
        return None
    owner_uid = os.environ.get("SUDO_UID") or str(os.getuid())
    lock_path = f"/tmp/rby1_policy_real_{owner_uid}.lock"
    lock_fd = os.open(lock_path, os.O_RDWR | os.O_CREAT, 0o600)
    try:
        fcntl.flock(lock_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        try:
            os.lseek(lock_fd, 0, os.SEEK_SET)
            detail = os.read(lock_fd, 4096).decode("utf-8", errors="replace").strip()
        finally:
            os.close(lock_fd)
        msg = (
            f"Another rollout_rby1_policy_real.py instance is still running "
            f"(lock: {lock_path})."
        )
        if detail:
            msg += f"\nExisting owner:\n{detail}"
        msg += "\nStop that process before starting a new hardware rollout."
        raise SystemExit(msg)

    os.ftruncate(lock_fd, 0)
    os.write(
        lock_fd,
        (
            f"pid={os.getpid()} pgid={os.getpgrp()} sid={os.getsid(0)} "
            f"started={datetime.datetime.now().isoformat(timespec='seconds')}\n"
            f"cmd={' '.join(sys.argv)}\n"
        ).encode("utf-8"),
    )
    os.fsync(lock_fd)
    return lock_fd


def _proc_cmdline(pid: int) -> str:
    try:
        raw = Path(f"/proc/{pid}/cmdline").read_bytes()
    except Exception:
        return ""
    return raw.replace(b"\x00", b" ").decode("utf-8", errors="replace").strip()


def _proc_pgid(pid: int) -> int | None:
    try:
        return os.getpgid(pid)
    except Exception:
        return None


def _proc_ppid(pid: int) -> int | None:
    try:
        for line in Path(f"/proc/{pid}/status").read_text(encoding="utf-8").splitlines():
            if line.startswith("PPid:"):
                return int(line.split()[1])
    except Exception:
        return None
    return None


def _ancestor_pids(pid: int) -> set[int]:
    ancestors: set[int] = set()
    current = pid
    while current > 1:
        parent = _proc_ppid(current)
        if parent is None or parent in ancestors:
            break
        ancestors.add(parent)
        current = parent
    return ancestors


def _find_stale_rollout_pids() -> list[int]:
    current_pid = os.getpid()
    current_pgid = os.getpgrp()
    current_sid = os.getsid(0)
    protected_pids = {current_pid, *_ancestor_pids(current_pid)}
    stale: list[int] = []
    proc_root = Path("/proc")
    for entry in proc_root.iterdir():
        if not entry.name.isdigit():
            continue
        pid = int(entry.name)
        if pid in protected_pids:
            continue
        cmd = _proc_cmdline(pid)
        if "rollout_rby1_policy_real.py" not in cmd:
            continue
        pgid = _proc_pgid(pid)
        if pgid == current_pgid:
            continue
        try:
            sid = os.getsid(pid)
        except Exception:
            sid = None
        if sid == current_sid and pgid == current_pgid:
            continue
        stale.append(pid)
    return stale


def _terminate_pids(pids: list[int], *, label: str, timeout_s: float = 1.0) -> None:
    if not pids:
        return
    print(f"[process] Cleaning stale {label} processes: {pids}", flush=True)
    for pid in pids:
        try:
            os.kill(pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        except PermissionError as exc:
            print(f"[process] No permission to SIGTERM pid={pid}: {exc}", flush=True)
    deadline = time.monotonic() + max(0.0, timeout_s)
    remaining = set(pids)
    while remaining and time.monotonic() < deadline:
        remaining = {pid for pid in remaining if Path(f"/proc/{pid}").exists()}
        if remaining:
            time.sleep(0.05)
    for pid in sorted(remaining):
        try:
            os.kill(pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        except PermissionError as exc:
            print(f"[process] No permission to SIGKILL pid={pid}: {exc}", flush=True)


def _cleanup_stale_rollouts(args: argparse.Namespace) -> None:
    if args.not_use_hardware or args.no_cleanup_stale_rollouts:
        return
    stale = _find_stale_rollout_pids()
    if stale:
        _terminate_pids(stale, label="rollout", timeout_s=1.0)



