# ---------------------------------------------------------------------------
# WebSocket policy client (from rollout_rby1_policy_sim.py)
# ---------------------------------------------------------------------------
class WebPolicyClient:
    def __init__(self, host: str, port: int):
        import msgpack_numpy
        import websockets.sync.client

        msgpack_numpy.patch()
        self._msgpack_numpy = msgpack_numpy
        self._uri = f"ws://{host}:{port}"
        self._conn = websockets.sync.client.connect(self._uri, compression=None, max_size=None)
        self.metadata = msgpack_numpy.unpackb(self._conn.recv())

    def infer(self, obs: dict) -> dict:
        packed = self._msgpack_numpy.packb(obs)
        self._conn.send(packed)
        response = self._conn.recv()
        if isinstance(response, str):
            raise RuntimeError(f"Server error: {response}")
        return self._msgpack_numpy.unpackb(response)

    def close(self) -> None:
        try:
            self._conn.close()
        except Exception:
            pass


def normalize_action_chunk(chunk: np.ndarray) -> np.ndarray:
    """Convert server response to (steps, action_dim). Handles (1,H,D), (H,D), or (D,)."""
    arr = np.asarray(chunk, dtype=np.float64)
    if arr.ndim == 3:
        arr = arr[0]
    if arr.ndim == 1:
        arr = arr[None, :]
    return arr


# ---------------------------------------------------------------------------
# Observation helpers
# ---------------------------------------------------------------------------
class AriaImageReader:
    """Cached shared-memory reader for the Aria policy image stream.

    Tracks the publisher's monotonic frame sequence so callers can detect stale /
    repeated frames and wait for a fresh capture before policy inference.
    """

    def __init__(self) -> None:
        self._shm = None
        self._shm_name: str | None = None
        self._shape: tuple[int, ...] | None = None
        self._last_seq = -1
        self._last_frame: np.ndarray | None = None
        self._last_ts = 0.0
        self._last_stall_warn_mono = 0.0

    def _close_shm(self) -> None:
        if self._shm is not None:
            try:
                self._shm.close()
            except Exception:
                pass
            self._shm = None

    def _attach(self, shm_name: str, shape: tuple[int, ...]) -> None:
        if self._shm is not None and self._shm_name == shm_name and self._shape == shape:
            return
        self._close_shm()
        self._shm_name = shm_name
        self._shape = shape
        self._shm = mp_shm.SharedMemory(name=shm_name)

    def read(
        self,
        aria_shared: dict | None,
    ) -> tuple[np.ndarray | None, float, int]:
        """Return (rgb_uint8_hwc, timestamp, frame_seq). Frame is None until shm exists."""
        if aria_shared is None:
            return self._last_frame, self._last_ts, self._last_seq

        ts = float(aria_shared.get(SHARED_KEY_TIMESTAMP) or 0.0)
        seq = int(aria_shared.get(SHARED_KEY_IMAGE_FRAME_SEQ) or -1)
        shm_name = aria_shared.get(SHARED_KEY_IMAGE_SHM_NAME)
        shape = aria_shared.get(SHARED_KEY_IMAGE_SHAPE)
        if shm_name is None or shape is None:
            return self._last_frame, ts, seq

        shape_t = tuple(int(x) for x in shape)
        try:
            self._attach(str(shm_name), shape_t)
            assert self._shm is not None
            frame = np.ndarray(shape=shape_t, dtype=np.uint8, buffer=self._shm.buf).copy()
        except Exception as exc:
            self._close_shm()
            print(colored(f"[aria] shared-memory read failed: {exc}", "yellow"))
            return self._last_frame, ts, seq

        self._last_frame = frame
        self._last_ts = ts
        self._last_seq = seq
        return frame, ts, seq

    def read_fresh(
        self,
        aria_shared: dict | None,
        after_seq: int,
        *,
        timeout_s: float = 1.5,
        stall_warn_s: float = 1.0,
    ) -> tuple[np.ndarray | None, float, int]:
        """Block briefly until frame_seq advances past *after_seq* (new Aria callback)."""
        deadline = time.monotonic() + max(0.0, timeout_s)
        frame: np.ndarray | None = None
        ts = 0.0
        seq = after_seq
        while time.monotonic() < deadline:
            frame, ts, seq = self.read(aria_shared)
            if frame is not None and seq > after_seq:
                return frame, ts, seq
            time.sleep(0.002)

        frame, ts, seq = self.read(aria_shared)
        if frame is not None and seq <= after_seq:
            now = time.monotonic()
            if now - self._last_stall_warn_mono >= stall_warn_s:
                self._last_stall_warn_mono = now
                print(
                    colored(
                        f"[aria] WARNING: no new RGB frame for policy "
                        f"(seq stuck at {seq}, waited {timeout_s:.2f}s)",
                        "yellow",
                    )
                )
        return frame, ts, seq

    def close(self) -> None:
        self._close_shm()


class _LockedAriaImageReader(AriaImageReader):
    """--bg-obs: the obs worker and the main loop's camera window share one reader.

    Each shared-memory read is serialized (read_fresh loops over read(), so it is locked
    per read, never for its whole wait)."""

    def __init__(self) -> None:
        super().__init__()
        self._bg_lock = threading.Lock()

    def read(self, aria_shared):
        with self._bg_lock:
            return super().read(aria_shared)


def _pcd_num_points_from_metadata(metadata: dict) -> int | None:
    """Probe server metadata for the DP3 cloud size (first dim of front_pcd_1)."""
    for container_key in ("obs_shapes", "observation_shapes", "shape_meta", "camera_shapes"):
        container = metadata.get(container_key)
        if not isinstance(container, dict):
            continue
        shape = container.get("front_pcd_1")
        if shape is None:
            continue
        try:
            shape_list = list(shape)
        except TypeError:
            continue
        if shape_list:
            return int(shape_list[0])
    if "front_pcd_1_num_points" in metadata:
        return int(metadata["front_pcd_1_num_points"])
    return None


def resolve_pcd_num_points(
    args: argparse.Namespace,
    metadata: dict,
    dataset_ref_obs: dict | None,
) -> int:
    """DP3 cloud size N: explicit arg > server metadata > dataset probe > 1024.

    N is baked into the checkpoint (the encoder asserts on point count), so a
    mismatch fails loudly server-side rather than mis-predicting silently.
    """
    if int(getattr(args, "pcd_num_points", 0) or 0) > 0:
        return int(args.pcd_num_points)
    meta_n = _pcd_num_points_from_metadata(metadata)
    if meta_n is not None and meta_n > 0:
        return meta_n
    if dataset_ref_obs is not None and "front_pcd_1" in dataset_ref_obs:
        arr = np.asarray(dataset_ref_obs["front_pcd_1"])
        if arr.ndim >= 2:
            return int(arr.shape[0])
    print(colored(
        "[percep] WARNING: could not resolve DP3 cloud size from --pcd-num-points, "
        "server metadata, or dataset; defaulting to 1024 (the recommended ckpt). "
        "A 2048 checkpoint will reject this obs.", "yellow",
    ))
    return 1024


def joint22_from_position(position: np.ndarray) -> np.ndarray:
    """22-D no-wheel proprio: torso, right arm, left arm, head."""
    pos = np.asarray(position, dtype=np.float32).reshape(-1)
    if pos.shape[0] < 26:
        raise ValueError(f"Expected position dim >= 26, got {pos.shape[0]}")
    return np.concatenate(
        [pos[4:10], pos[10:17], pos[17:24], pos[24:26]], dtype=np.float32
    )


def acquire_live_aria_frame_for_policy(
    reader: AriaImageReader,
    aria_shared: dict | None,
    after_seq: int,
    *,
    timeout_s: float = 2.0,
) -> tuple[np.ndarray | None, float, int]:
    """Wait until Aria publishes a frame with seq > after_seq (for policy inference)."""
    deadline = time.monotonic() + max(0.1, timeout_s)
    frame: np.ndarray | None = None
    ts = 0.0
    seq = after_seq
    while time.monotonic() < deadline:
        frame, ts, seq = reader.read_fresh(
            aria_shared,
            after_seq,
            timeout_s=min(0.5, max(0.05, deadline - time.monotonic())),
        )
        if frame is not None and seq > after_seq:
            return frame, ts, seq
        time.sleep(0.005)
    frame, ts, seq = reader.read(aria_shared)
    return frame, ts, seq


def read_aria_image(
    aria_shared: Optional[dict],
    last_frame: Optional[np.ndarray],
    reader: AriaImageReader | None = None,
) -> tuple[Optional[np.ndarray], float]:
    """Read latest Aria RGB image from shared memory (legacy 2-tuple API)."""
    if reader is not None:
        frame, ts, _seq = reader.read(aria_shared)
        if frame is not None:
            return frame, ts
        return last_frame, ts
    if aria_shared is None:
        return last_frame, 0.0
    ts = float(aria_shared.get(SHARED_KEY_TIMESTAMP) or 0.0)
    shm_name = aria_shared.get(SHARED_KEY_IMAGE_SHM_NAME)
    shape = aria_shared.get(SHARED_KEY_IMAGE_SHAPE)
    if shm_name is None or shape is None:
        return last_frame, ts
    try:
        shm = mp_shm.SharedMemory(name=shm_name)
        frame = np.ndarray(shape=shape, dtype=np.uint8, buffer=shm.buf).copy()
        shm.close()
        return frame, ts
    except Exception:
        return last_frame, ts


def read_aria_board_transformation(
    aria_shared: Optional[dict],
    last_transform: Optional[np.ndarray],
) -> tuple[Optional[np.ndarray], float]:
    """Read latest fused AprilTag board pose T_cam_board from Aria shared state."""
    if aria_shared is None:
        return last_transform, 0.0
    ts = float(aria_shared.get(SHARED_KEY_TIMESTAMP) or 0.0)
    try:
        T_cam_board = read_aria_T_cam_board(aria_shared)
    except Exception:
        return last_transform, ts
    if T_cam_board is None:
        return last_transform, ts
    return np.asarray(T_cam_board, dtype=np.float32).reshape(4, 4), ts


def get_head2_to_upper_transformation_fk(
    position: np.ndarray,
    torso_transforms: dict,
    head_transforms: dict,
) -> np.ndarray:
    """
    Compute T_head2_to_upper from live robot state using geometric FK.
    """
    pos = np.asarray(position, dtype=np.float64).reshape(-1)
    if pos.shape[0] < 26:
        raise ValueError(
            f"Expected position with >=26 joints for torso/head slices, got {pos.shape[0]}"
        )
    q_torso = pos[4:10]
    q_head = pos[24:26]

    torso_fk = geo_kin_rby1.get_robot_Torso_from_q(q_torso, torso_transforms)
    head_fk = geo_kin_rby1.get_robot_Head_from_q(q_head, head_transforms)

    p_world_upper = np.asarray(torso_fk["p_upper"], dtype=np.float64).reshape(3)
    R_world_upper = np.asarray(torso_fk["R_upper"], dtype=np.float64).reshape(3, 3)
    p_world_hbase = np.asarray(torso_fk["p_head_base"], dtype=np.float64).reshape(3)
    R_world_hbase = np.asarray(torso_fk["R_head_base"], dtype=np.float64).reshape(3, 3)
    p_hbase_head2 = np.asarray(head_fk["p_hbase_2"], dtype=np.float64).reshape(3)
    R_hbase_head2 = np.asarray(head_fk["R_hbase_2"], dtype=np.float64).reshape(3, 3)

    p_world_head2 = p_world_hbase + R_world_hbase @ p_hbase_head2
    R_world_head2 = R_world_hbase @ R_hbase_head2

    T_world_upper = np.eye(4, dtype=np.float64)
    T_world_upper[:3, :3] = R_world_upper
    T_world_upper[:3, 3] = p_world_upper
    T_world_head2 = np.eye(4, dtype=np.float64)
    T_world_head2[:3, :3] = R_world_head2
    T_world_head2[:3, 3] = p_world_head2
    T_head2_upper = np.linalg.inv(T_world_head2) @ T_world_upper
    return T_head2_upper.astype(np.float32, copy=False)

