def board_2_robot_center(
    position: np.ndarray,
    T_cam_board: np.ndarray,
    torso_transforms: dict,
    head_transforms: dict,
):
    """
    T_cam_board: cam <- board
    Returns:     upper <- board
    """
    T_cam_from_head = np.asarray(CAM2HEAD, dtype=np.float32).reshape(4, 4)
    T_cam_from_board = np.asarray(T_cam_board, dtype=np.float32).reshape(4, 4)

    # despite the name, this function currently returns: head <- upper
    T_head_from_upper = get_head2_to_upper_transformation_fk(
        position, torso_transforms, head_transforms
    )

    # correct chaining order
    T_cam_from_upper = T_cam_from_head @ T_head_from_upper
    T_upper_from_cam = np.linalg.inv(T_cam_from_upper)

    T_upper_from_board = T_upper_from_cam @ T_cam_from_board
    return T_upper_from_board.astype(np.float32, copy=False)


def _draw_apriltag_pose_in_world(
    viewer,
    torso_q: np.ndarray,
    torso_transforms: dict,
    T_upper_board: np.ndarray,
) -> None:
    """
    Draw AprilTag board pose in MuJoCo viewer using upper-frame->world projection.
    Visualization: one large center marker + dense axis points (x/red, y/green, z/blue)
    to make the TF frame obvious in the MuJoCo viewer.
    NOTE: verified by human
    """
    T_upper_board = np.asarray(T_upper_board, dtype=np.float64).reshape(4, 4)
    if not np.all(np.isfinite(T_upper_board)):
        return
    fk = geo_kin_rby1.get_robot_Torso_from_q(
        np.asarray(torso_q, dtype=np.float64).reshape(6), torso_transforms
    )
    p_world_upper = np.asarray(fk["p_upper"], dtype=np.float64).reshape(3)
    R_world_upper = np.asarray(fk["R_upper"], dtype=np.float64).reshape(3, 3)

    p_upper_board = T_upper_board[:3, 3]
    R_upper_board = T_upper_board[:3, :3]
    p_world_board = p_world_upper + R_world_upper @ p_upper_board
    R_world_board = R_world_upper @ R_upper_board

    scene = viewer.user_scn
    needed = 1 + 3 * APRIL_TAG_AXIS_POINTS
    if scene.ngeom + needed > scene.maxgeom:
        return

    # print(
        # "[apriltag][viz_world] "
        # f"x={p_world_board[0]:.4f} y={p_world_board[1]:.4f} z={p_world_board[2]:.4f}"
    # )

    mujoco.mjv_initGeom(
        scene.geoms[scene.ngeom],
        type=mujoco.mjtGeom.mjGEOM_SPHERE,
        size=[APRIL_TAG_MARKER_RADIUS, 0.0, 0.0],
        pos=p_world_board,
        mat=np.eye(3).flatten(),
        rgba=np.array([1.0, 0.2, 0.2, 0.95], dtype=np.float32),
    )
    scene.ngeom += 1

    axis_colors = (
        np.array([1.0, 0.1, 0.1, 0.95], dtype=np.float32),  # x
        np.array([0.1, 1.0, 0.1, 0.95], dtype=np.float32),  # y
        np.array([0.1, 0.3, 1.0, 0.95], dtype=np.float32),  # z
    )
    for i, rgba in enumerate(axis_colors):
        axis_dir = R_world_board[:, i]
        for j in range(APRIL_TAG_AXIS_POINTS):
            alpha = float(j + 1) / float(APRIL_TAG_AXIS_POINTS)
            p_axis = p_world_board + axis_dir * (APRIL_TAG_AXIS_LEN * alpha)
            size = (
                APRIL_TAG_AXIS_TIP_RADIUS
                if j == APRIL_TAG_AXIS_POINTS - 1
                else APRIL_TAG_AXIS_POINT_RADIUS
            )
            mujoco.mjv_initGeom(
                scene.geoms[scene.ngeom],
                type=mujoco.mjtGeom.mjGEOM_SPHERE,
                size=[size, 0.0, 0.0],
                pos=p_axis,
                mat=np.eye(3).flatten(),
                rgba=rgba,
            )
            scene.ngeom += 1


def _draw_tf_pose_in_world(
    viewer,
    torso_q: np.ndarray,
    torso_transforms: dict,
    T_upper_target: np.ndarray,
    *,
    label: str,
    origin_rgba: np.ndarray,
    debug: bool = False,    
) -> None:
    """
    Draw a generic TF pose given as T_upper_target in world coordinates.
    """
    T_upper_target = np.asarray(T_upper_target, dtype=np.float64).reshape(4, 4)
    if not np.all(np.isfinite(T_upper_target)):
        return
    fk = geo_kin_rby1.get_robot_Torso_from_q(
        np.asarray(torso_q, dtype=np.float64).reshape(6), torso_transforms
    )
    p_world_upper = np.asarray(fk["p_upper"], dtype=np.float64).reshape(3)
    R_world_upper = np.asarray(fk["R_upper"], dtype=np.float64).reshape(3, 3)
    p_world_target = p_world_upper + R_world_upper @ T_upper_target[:3, 3]
    R_world_target = R_world_upper @ T_upper_target[:3, :3]

    scene = viewer.user_scn
    needed = 1 + 3 * APRIL_TAG_AXIS_POINTS
    if scene.ngeom + needed > scene.maxgeom:
        return

    if debug:
        print(
            f"[tf][{label}][viz_world] "
            f"x={p_world_target[0]:.4f} y={p_world_target[1]:.4f} z={p_world_target[2]:.4f}"
        )

    mujoco.mjv_initGeom(
        scene.geoms[scene.ngeom],
        type=mujoco.mjtGeom.mjGEOM_SPHERE,
        size=[APRIL_TAG_MARKER_RADIUS, 0.0, 0.0],
        pos=p_world_target,
        mat=np.eye(3).flatten(),
        rgba=np.asarray(origin_rgba, dtype=np.float32),
    )
    scene.ngeom += 1

    axis_colors = (
        np.array([1.0, 0.1, 0.1, 0.95], dtype=np.float32),
        np.array([0.1, 1.0, 0.1, 0.95], dtype=np.float32),
        np.array([0.1, 0.3, 1.0, 0.95], dtype=np.float32),
    )
    for i, rgba in enumerate(axis_colors):
        axis_dir = R_world_target[:, i]
        for j in range(APRIL_TAG_AXIS_POINTS):
            alpha = float(j + 1) / float(APRIL_TAG_AXIS_POINTS)
            p_axis = p_world_target + axis_dir * (APRIL_TAG_AXIS_LEN * alpha)
            size = (
                APRIL_TAG_AXIS_TIP_RADIUS
                if j == APRIL_TAG_AXIS_POINTS - 1
                else APRIL_TAG_AXIS_POINT_RADIUS
            )
            mujoco.mjv_initGeom(
                scene.geoms[scene.ngeom],
                type=mujoco.mjtGeom.mjGEOM_SPHERE,
                size=[size, 0.0, 0.0],
                pos=p_axis,
                mat=np.eye(3).flatten(),
                rgba=rgba,
            )
            scene.ngeom += 1


def _draw_upper_to_cam_in_world(
    viewer,
    torso_q: np.ndarray,
    torso_transforms: dict,
    T_upper_2_cam: np.ndarray,
) -> None:
    """Visualize T_upper_to_cam as a world-frame TF triad."""
    _draw_tf_pose_in_world(
        viewer,
        torso_q,
        torso_transforms,
        T_upper_2_cam,
        label="upper_to_cam",
        origin_rgba=np.array([1.0, 0.85, 0.1, 0.95], dtype=np.float32),
    )


def _draw_head2_to_upper_in_world(
    viewer,
    torso_q: np.ndarray,
    torso_transforms: dict,
    T_head2_2_upper: np.ndarray,
) -> None:
    """
    Visualize head_2 frame using T_head2_to_upper by inverting to T_upper_to_head2.
    """
    T_upper_2_head2 = np.linalg.inv(np.asarray(T_head2_2_upper, dtype=np.float64).reshape(4, 4))
    _draw_tf_pose_in_world(
        viewer,
        torso_q,
        torso_transforms,
        T_upper_2_head2,
        label="head2_in_upper",
        origin_rgba=np.array([0.95, 0.1, 1.0, 0.95], dtype=np.float32),
    )


def _robot0_joint_pos_len(
    metadata: dict,
    position: np.ndarray,
    override: int | None,
) -> int:
    """Match policy/dataset width for `robot0_joint_pos`."""
    if override is not None and override > 0:
        return int(override)
    r = metadata.get("robot0_joint_pos_dim")
    if r is not None:
        return int(r)
    pos = np.asarray(position, dtype=np.float64).ravel()
    return int(max(26, pos.shape[0]))


def _hand_qpos_12(h: np.ndarray) -> np.ndarray:
    h = np.asarray(h, dtype=np.float32).reshape(-1)
    if h.size >= 12:
        return h[:12].copy()
    return np.pad(h, (0, max(0, 12 - h.size)))


def _wrap_angle_delta(angle: float) -> float:
    return float(np.arctan2(np.sin(angle), np.cos(angle)))


class RolloutBasePoseIntegrator:
    """Rollout-local base pose, zeroed at the first rollout odom sample."""

    def __init__(self, output_initial_pose: np.ndarray | None = None) -> None:
        self._origin_pose: np.ndarray | None = None
        self._last_odom_time: float | None = None
        if output_initial_pose is None:
            self._output_initial_pose = np.zeros(3, dtype=np.float64)
        else:
            self._output_initial_pose = np.asarray(
                output_initial_pose, dtype=np.float64
            ).reshape(3)
        self._pose = self._output_initial_pose.copy()

    def current_pose(self) -> np.ndarray:
        return self._pose.astype(np.float32, copy=True)

    @property
    def last_odom_time(self) -> float | None:
        return self._last_odom_time

    @property
    def origin_set(self) -> bool:
        return self._origin_pose is not None

    def start_frame_yaw_in_odom(self) -> float | None:
        """Heading of the observation/start frame expressed in the odometry frame (rad).

        None until the first odom sample. Equals the origin heading unless the observation
        frame was seeded with a non-zero heading (``output_initial_pose`` after a base reset).
        """
        if self._origin_pose is None:
            return None
        return float(self._origin_pose[2]) - float(self._output_initial_pose[2])

    def start_frame_delta_to_odom(self, dx: float, dy: float) -> tuple[float, float] | None:
        """Rotate a translation delta from the start frame into the wheel-odometry frame.

        Inverse of the rotation ``update`` applies to odometry displacements, so a delta
        applied here shows up as the same delta in ``current_pose``.
        """
        psi = self.start_frame_yaw_in_odom()
        if psi is None:
            return None
        c = float(np.cos(psi))
        s = float(np.sin(psi))
        return (c * dx - s * dy, s * dx + c * dy)

    def update(self, odom: tuple[float, ...] | np.ndarray | None) -> np.ndarray:
        if odom is None:
            return self._pose.astype(np.float32, copy=True)

        odom_arr = np.asarray(odom, dtype=np.float64).reshape(-1)
        if odom_arr.size < 3 or not np.all(np.isfinite(odom_arr[:3])):
            return self._pose.astype(np.float32, copy=True)
        odom_pose = odom_arr[:3].copy()
        odom_time = float(odom_arr[3]) if odom_arr.size >= 4 else None

        if self._origin_pose is None:
            self._origin_pose = odom_pose
            self._last_odom_time = odom_time
            self._pose[:] = self._output_initial_pose
            return self._pose.astype(np.float32, copy=True)

        if odom_time is not None and self._last_odom_time is not None:
            if odom_time <= self._last_odom_time:
                return self._pose.astype(np.float32, copy=True)

        dx_world = odom_pose[0] - self._origin_pose[0]
        dy_world = odom_pose[1] - self._origin_pose[1]
        th0 = self._origin_pose[2]
        c0 = float(np.cos(th0))
        s0 = float(np.sin(th0))
        dx_local = c0 * dx_world + s0 * dy_world
        dy_local = -s0 * dx_world + c0 * dy_world
        dtheta = _wrap_angle_delta(odom_pose[2] - th0)
        x0, y0, th_out0 = self._output_initial_pose
        cout = float(np.cos(th_out0))
        sout = float(np.sin(th_out0))
        self._pose[0] = x0 + cout * dx_local - sout * dy_local
        self._pose[1] = y0 + sout * dx_local + cout * dy_local
        self._pose[2] = th_out0 + dtheta
        self._last_odom_time = odom_time
        return self._pose.astype(np.float32, copy=True)


class BaseDeltaCommandAdapter:
    """Convert the policy's per-row base delta into the delta the SE2 goal follower expects.

    The policy (and the dataset it was trained on) expresses base deltas in the rollout START
    frame — the frame ``RolloutBasePoseIntegrator`` builds ``base_pose_integrated`` in (see
    ``_integrate_base_deltas_base_frame``: "do not rotate XY by the running yaw"). The follower
    (``BaseSE2FeedbackControl.set_goal_delta``) adds deltas in the raw wheel-odometry frame.
    The two frames differ by the odometry heading at the integrator's origin (minus the heading
    the observation frame was seeded with after a base reset), so until 2026-10-13 every delta
    was rotated by that heading whenever the robot did not start at odometry yaw 0.

    frame="start" (default): rotate (dx, dy) into the odometry frame — the same rotation
    ``_relative_pose_to_odom_goal`` applies to the base-reset target. dyaw is frame-free.
    frame="odom": the previous behaviour, deltas passed through unchanged (explicit opt-out,
    ``--base-delta-frame odom`` / launcher ``BASE_DELTA_FRAME=odom``).
    """

    def __init__(self, frame: str, integrator: RolloutBasePoseIntegrator) -> None:
        if frame not in ("start", "odom"):
            raise ValueError(f"unknown base delta frame '{frame}' (expected 'start' or 'odom')")
        self.frame = frame
        self.integrator = integrator
        self._announced = False
        self._warned_no_origin = False

    def to_odom(self, base_delta, odom_getter=None) -> tuple[float, float, float]:
        d = np.asarray(base_delta, dtype=np.float64).reshape(3)
        dx, dy, dyaw = float(d[0]), float(d[1]), float(d[2])
        if self.frame == "odom":
            return dx, dy, dyaw
        if not self.integrator.origin_set and odom_getter is not None:
            # Same call the observation path makes; it only seeds the origin when odometry is
            # ready (the observation path has normally done this already at the first obs).
            self.integrator.update(odom_getter())
        rotated = self.integrator.start_frame_delta_to_odom(dx, dy)
        if rotated is None:
            if not self._warned_no_origin:
                print(
                    colored(
                        "[base] odometry origin unknown — base deltas passed through in the raw "
                        "odometry frame until it is",
                        "yellow",
                    )
                )
                self._warned_no_origin = True
            return dx, dy, dyaw
        if not self._announced:
            psi = self.integrator.start_frame_yaw_in_odom()
            print(
                "[base] start-frame base deltas are rotated into the odometry frame by "
                f"{np.degrees(psi):.1f} deg (--base-delta-frame start)"
            )
            self._announced = True
        return rotated[0], rotated[1], dyaw


class BasePoseHistoryWindow:
    """Build body-frame past waypoint windows from timestamped absolute base poses."""

    def __init__(
        self,
        *,
        window_size: int,
        window_delta_frames: int,
        history_fps: float,
    ) -> None:
        if window_size <= 0:
            raise ValueError("window_size must be > 0")
        if window_delta_frames <= 0:
            raise ValueError("window_delta_frames must be > 0")
        if history_fps <= 0:
            raise ValueError("history_fps must be > 0")
        self.window_size = int(window_size)
        self.window_delta_frames = int(window_delta_frames)
        self.history_fps = float(history_fps)
        self.lag_seconds = np.asarray(
            [
                (k * self.window_delta_frames) / self.history_fps
                for k in range(1, self.window_size + 1)
            ],
            dtype=np.float64,
        )
        self._samples: deque[tuple[float, np.ndarray]] = deque()

    def seed_from_window(
        self,
        current_pose: np.ndarray,
        window: np.ndarray,
        *,
        now: float | None = None,
    ) -> None:
        current = np.asarray(current_pose, dtype=np.float64).reshape(3)
        window_arr = np.asarray(window, dtype=np.float64).reshape(self.window_size, 3)
        t_now = time.monotonic() if now is None else float(now)
        self._samples.clear()

        for i in range(self.window_size - 1, -1, -1):
            dx_body, dy_body, dtheta = window_arr[i]
            c = float(np.cos(current[2]))
            s = float(np.sin(current[2]))
            past = np.array(
                [
                    current[0] + c * dx_body - s * dy_body,
                    current[1] + s * dx_body + c * dy_body,
                    current[2] + dtheta,
                ],
                dtype=np.float64,
            )
            self._samples.append((t_now - float(self.lag_seconds[i]), past))
        self._samples.append((t_now, current.copy()))

    def record(self, current_pose: np.ndarray, *, now: float | None = None) -> np.ndarray:
        """Store one absolute base pose sample without building an observation."""
        current = np.asarray(current_pose, dtype=np.float64).reshape(3)
        t_now = time.monotonic() if now is None else float(now)
        if self._samples and t_now <= self._samples[-1][0]:
            self._samples[-1] = (t_now, current.copy())
        else:
            self._samples.append((t_now, current.copy()))
        self._trim(t_now)
        return current.astype(np.float32, copy=True)

    def update(self, current_pose: np.ndarray, *, now: float | None = None) -> np.ndarray:
        t_now = time.monotonic() if now is None else float(now)
        current = self.record(current_pose, now=t_now).astype(np.float64)
        return self._window_at(current, t_now).astype(np.float32, copy=False)

    def _trim(self, now: float) -> None:
        oldest_keep = float(now) - float(self.lag_seconds[-1]) - 1.0
        while len(self._samples) > 1 and self._samples[1][0] < oldest_keep:
            self._samples.popleft()

    def _sample_at(self, target_time: float) -> np.ndarray:
        if not self._samples:
            return np.zeros(3, dtype=np.float64)
        if target_time <= self._samples[0][0]:
            return self._samples[0][1].copy()
        if target_time >= self._samples[-1][0]:
            return self._samples[-1][1].copy()

        prev_t, prev_pose = self._samples[0]
        for next_t, next_pose in list(self._samples)[1:]:
            if target_time <= next_t:
                alpha = (target_time - prev_t) / max(next_t - prev_t, 1e-9)
                out = (1.0 - alpha) * prev_pose + alpha * next_pose
                out[2] = prev_pose[2] + alpha * _wrap_angle_delta(
                    float(next_pose[2] - prev_pose[2])
                )
                return out
            prev_t, prev_pose = next_t, next_pose
        return self._samples[-1][1].copy()

    def _window_at(self, current_pose: np.ndarray, now: float) -> np.ndarray:
        current = np.asarray(current_pose, dtype=np.float64).reshape(3)
        c = float(np.cos(current[2]))
        s = float(np.sin(current[2]))
        out = np.zeros((self.window_size, 3), dtype=np.float64)
        for i, lag_s in enumerate(self.lag_seconds):
            past = self._sample_at(float(now) - float(lag_s))
            dx_w = past[0] - current[0]
            dy_w = past[1] - current[1]
            out[i] = (
                c * dx_w + s * dy_w,
                -s * dx_w + c * dy_w,
                past[2] - current[2],
            )
        return out.reshape(self.window_size * 3)


def resize_policy_image(frame: np.ndarray, size: int) -> np.ndarray:
    """Resize a HxWx3 uint8 frame to (size, size, 3). Server does no resizing.

    The HPT ResNet stem emits one token per conv cell, so the input resolution must
    match training (e.g. 224) or the image-token count (and feature stats) change.
    INTER_AREA for downscale, INTER_LINEAR for upscale.
    """
    if size <= 0:
        return frame
    frame = np.asarray(frame, dtype=np.uint8)
    if frame.ndim != 3 or frame.shape[2] != 3:
        return frame
    if frame.shape[0] == size and frame.shape[1] == size:
        return frame
    interp = cv2.INTER_AREA if frame.shape[0] > size else cv2.INTER_LINEAR
    return cv2.resize(frame, (size, size), interpolation=interp).astype(np.uint8)


_POLICY_CAM_WINDOW = "policy camera (exact BGR frame sent to server)"


def show_policy_camera_window(
    frame: np.ndarray,
    policy_image_size: int,
    display_size: int = 448,
) -> None:
    """Pop up the exact BGR frame sent to the server (after the 224 resize)."""
    if frame is None:
        return
    sent = resize_policy_image(np.asarray(frame, dtype=np.uint8), policy_image_size)
    disp = cv2.resize(
        sent, (display_size, display_size), interpolation=cv2.INTER_NEAREST
    )
    cv2.putText(
        disp,
        f"{sent.shape[1]}x{sent.shape[0]} BGR->server",
        (8, 24),
        cv2.FONT_HERSHEY_SIMPLEX,
        0.6,
        (0, 255, 0),
        2,
        cv2.LINE_AA,
    )
    cv2.imshow(_POLICY_CAM_WINDOW, disp)
    cv2.waitKey(1)


_PERCEP_WINDOW = "perception (rect-left | depth) -> policy obs"


def show_perception_window(preview_bgr: np.ndarray | None, display_h: int = 360) -> None:
    """Aspect-preserving pop-up of the perception preview composite."""
    if preview_bgr is None:
        return
    h, w = preview_bgr.shape[:2]
    disp_w = max(1, int(round(w * display_h / max(1, h))))
    disp = cv2.resize(preview_bgr, (disp_w, display_h), interpolation=cv2.INTER_NEAREST)
    cv2.imshow(_PERCEP_WINDOW, disp)
    cv2.waitKey(1)


def save_image_compare_pair(
    out_dir: str,
    idx: int,
    sent_bgr: np.ndarray | None,
    live_bgr: np.ndarray | None,
) -> None:
    """Write the policy-input image and the live Aria frame for one inference.

    Both frames are BGR in memory, matching the EgoVerse server input convention.
    Files are matched by index: ``sent_<idx>.png`` (what the policy saw) and
    ``live_<idx>.png`` (the true current Aria frame at that inference time).
    """
    os.makedirs(out_dir, exist_ok=True)
    if sent_bgr is not None:
        cv2.imwrite(
            os.path.join(out_dir, f"sent_{idx:05d}.png"),
            np.asarray(sent_bgr, dtype=np.uint8),
        )
    if live_bgr is not None:
        cv2.imwrite(
            os.path.join(out_dir, f"live_{idx:05d}.png"),
            np.asarray(live_bgr, dtype=np.uint8),
        )


_GT_COMPARE_WINDOW = "GT obs (train) vs LIVE obs  +  action to carry"


def _action_summary_lines(action_row: np.ndarray | None) -> list[str]:
    """Compact per-block summary of a 49-D action row.

    Layout: base[0:3] torso[3:9] head[9:11] L-arm[11:18] R-arm[18:25]
    L-hand[25:37] R-hand[37:49]. Hands shown as means to keep it readable.
    """
    if action_row is None:
        return ["action: <none>"]
    a = np.asarray(action_row, dtype=np.float64)
    if a.ndim == 2:
        a = a[0]
    a = a.reshape(-1)

    def fmt(s: int, e: int) -> str:
        if a.shape[0] < e:
            return "n/a"
        return np.array2string(a[s:e], precision=2, suppress_small=True, max_line_width=260)

    lines: list[str] = []
    if a.shape[0] >= 11:
        lines.append(f"base {fmt(0, 3)}   head {fmt(9, 11)}")
        lines.append(f"torso {fmt(3, 9)}")
    if a.shape[0] >= 25:
        lines.append(f"L-arm {fmt(11, 18)}")
        lines.append(f"R-arm {fmt(18, 25)}")
    if a.shape[0] >= 49:
        lines.append(
            f"L-hand mean {float(np.mean(a[25:37])):+.2f}   "
            f"R-hand mean {float(np.mean(a[37:49])):+.2f}"
        )
    if not lines:
        lines.append(np.array2string(a, precision=2, suppress_small=True, max_line_width=260))
    return lines


def show_gt_obs_compare_window(
    live_bgr: np.ndarray | None,
    gt_bgr: np.ndarray | None,
    action_row: np.ndarray | None = None,
    *,
    step: int | None = None,
    panel: int = 320,
) -> None:
    """Pop a window comparing the GT training obs (left) with the current live obs
    (right), labeled, plus the action that will be carried out printed underneath.

    Images are BGR in memory, matching the EgoVerse server input convention.
    """

    def _mk(img: np.ndarray | None, label: str) -> np.ndarray:
        if not isinstance(img, np.ndarray) or img.ndim != 3 or img.shape[2] != 3:
            p = np.zeros((panel, panel, 3), dtype=np.uint8)
            cv2.putText(p, "<no frame>", (8, panel // 2), cv2.FONT_HERSHEY_SIMPLEX,
                        0.6, (0, 0, 255), 2, cv2.LINE_AA)
        else:
            p = cv2.resize(
                np.ascontiguousarray(img, dtype=np.uint8),
                (panel, panel),
                interpolation=cv2.INTER_NEAREST,
            )
        cv2.putText(p, label, (8, 24), cv2.FONT_HERSHEY_SIMPLEX, 0.6, (0, 255, 0), 2, cv2.LINE_AA)
        return p

    combo = np.hstack([_mk(gt_bgr, "GT obs (train)"), _mk(live_bgr, "LIVE obs (now)")])
    lines = _action_summary_lines(action_row)
    if step is not None:
        lines = [f"step {step} | action to carry:"] + lines
    bar = np.zeros((22 * len(lines) + 12, combo.shape[1], 3), dtype=np.uint8)
    for i, ln in enumerate(lines):
        cv2.putText(bar, ln, (8, 20 + i * 22), cv2.FONT_HERSHEY_SIMPLEX,
                    0.45, (255, 255, 255), 1, cv2.LINE_AA)
    cv2.imshow(_GT_COMPARE_WINDOW, np.vstack([combo, bar]))
    cv2.waitKey(1)


def confirm_yn_keep_camera(
    prompt: str,
    *,
    frame: np.ndarray | None = None,
    policy_image_size: int = 0,
    show_camera: bool = False,
    aria_shared: dict | None = None,
    aria_reader: AriaImageReader | None = None,
) -> bool:
    """Read a y/N answer from stdin while keeping the OpenCV window responsive.

    The camera window only paints when cv2.waitKey runs; a blocking input() lets it go
    'not responding'. Here we poll stdin with select() and pump the window each loop, so you
    can inspect the live frame while deciding. Returns True on y/yes.

    When *aria_shared* + *aria_reader* are provided, each loop reads the latest Aria frame
    instead of re-displaying a stale snapshot captured at inference time.
    """
    if not show_camera:
        return input(prompt).strip().lower() in ("y", "yes")
    sys.stdout.write(prompt)
    sys.stdout.flush()
    while True:
        live = frame
        if aria_shared is not None and aria_reader is not None:
            live, _, _ = aria_reader.read(aria_shared)
        if live is not None:
            show_policy_camera_window(live, policy_image_size)
        else:
            cv2.waitKey(50)
        ready, _, _ = select.select([sys.stdin], [], [], 0.05)
        if ready:
            return sys.stdin.readline().strip().lower() in ("y", "yes")


def build_hardware_policy_obs_payload(
    *,
    metadata: dict,
    position: np.ndarray,
    aria_frame: np.ndarray | None,
    last_hand_left: np.ndarray,
    last_hand_right: np.ndarray,
    T_upper_board: np.ndarray,
    base_pose_integrated: np.ndarray | None,
    zero_obs: bool,
    task_id: int,
    robot0_joint_pos_len_override: int | None,
    policy_image_size: int = 0,
    override_obs: dict | None = None,
) -> dict:
    """
    Build websocket obs from live hardware + Aria, keyed by server metadata (same contract as sim).
    Camera tensors share one frame; unknown keys raise with a clear error.

    ``override_obs`` supplies per-key observation tensors (e.g. the live DP3
    ``front_pcd_1`` cloud or the Adapt3R rect-gray ``front_img_1`` +
    ``aria_depth``) that win over the default fill for any metadata key, and
    are additionally included even when metadata does not list them (the
    server ignores extras). ``aria_frame=None`` is allowed when every camera
    key is covered by ``override_obs`` (a zero image backs any remainder).
    """
    cam_keys = list(dict.fromkeys(metadata.get("camera_keys") or []))
    proprio_keys = list(dict.fromkeys(metadata.get("proprio_keys") or []))
    all_keys = list(dict.fromkeys(cam_keys + proprio_keys))
    override_obs = override_obs or {}

    pos = np.asarray(position, dtype=np.float32).ravel()
    rlen = _robot0_joint_pos_len(metadata, position, robot0_joint_pos_len_override)

    def robot0_joint_pos_26() -> np.ndarray:
        out = np.zeros(max(26, pos.shape[0]), dtype=np.float32)
        out[: pos.shape[0]] = pos
        return out[:26]

    def robot0_joint_pos() -> np.ndarray:
        if rlen == 22:
            return robot0_joint_pos_26()[4:26].copy()
        out = np.zeros(rlen, dtype=np.float32)
        n = min(out.shape[0], pos.shape[0])
        out[:n] = pos[:n]
        return out

    if aria_frame is None:
        side = int(policy_image_size) if policy_image_size else 224
        aria = np.zeros((side, side, 3), dtype=np.uint8)
    else:
        aria = resize_policy_image(np.asarray(aria_frame, dtype=np.uint8), policy_image_size)
    cam_img = np.zeros_like(aria) if zero_obs else aria
    T_upper_board = np.asarray(T_upper_board, dtype=np.float32).reshape(4, 4)
    p_upper_board = T_upper_board[:3, 3].astype(np.float32)
    rotvec_upper_board = (
        Rotation.from_matrix(T_upper_board[:3, :3].astype(np.float64))
        .as_rotvec()
        .astype(np.float32)
    )
    base_pose_obs = (
        np.zeros(3, dtype=np.float32)
        if base_pose_integrated is None
        else np.asarray(base_pose_integrated, dtype=np.float32).reshape(-1)
    )

    payload: dict = {}
    for k in all_keys:
        if k == "task_id":
            continue
        if k in override_obs:
            payload[k] = override_obs[k]
        elif k in cam_keys:
            payload[k] = cam_img.copy()
        elif k == "robot0_joint_pos":
            payload[k] = robot0_joint_pos()
        elif k == "robot0_joint_pos_no_wheel":
            payload[k] = robot0_joint_pos_26()[4:26].copy()
        elif k == "right_arm":
            payload[k] = pos[10:17].copy() if pos.shape[0] >= 17 else np.zeros(7, dtype=np.float32)
        elif k == "left_arm":
            payload[k] = pos[17:24].copy() if pos.shape[0] >= 24 else np.zeros(7, dtype=np.float32)
        elif k == "hand_right_qpos":
            payload[k] = _hand_qpos_12(last_hand_right)
        elif k == "hand_left_qpos":
            payload[k] = _hand_qpos_12(last_hand_left)
        elif k in ("base_pose_integrated", "obs.base_pose_integrated"):
            payload[k] = np.zeros_like(base_pose_obs) if zero_obs else base_pose_obs.copy()
        elif k in ("april_tag_xyz", "apriltag_xyz"):
            payload[k] = np.zeros(3, dtype=np.float32) if zero_obs else p_upper_board.copy()
        elif k in ("april_tag", "apriltag"):
            if zero_obs:
                payload[k] = np.zeros(6, dtype=np.float32)
            else:
                payload[k] = np.concatenate((p_upper_board, rotvec_upper_board)).astype(np.float32)
        elif k in ("robot0_joint_pos_hist", "base_traj"):
            continue
        else:
            raise KeyError(
                f"Hardware rollout: unsupported observation key {k!r}. "
                "Supported proprio: robot0_joint_pos, robot0_joint_pos_no_wheel, "
                "right_arm, left_arm, hand_left_qpos, "
                "hand_right_qpos, base_pose_integrated, april_tag_xyz/apriltag_xyz, "
                "april_tag/apriltag, task_id. "
                "Camera keys: any name in metadata camera_keys "
                "(same image per key). Extend build_hardware_policy_obs_payload if needed."
            )

    if "robot0_joint_pos" in payload:
        payload["robot0_joint_pos_no_wheel"] = (
            payload["robot0_joint_pos"]
            if payload["robot0_joint_pos"].shape[0] == 22
            else robot0_joint_pos_26()[4:26].copy()
        )
    payload["base_pose_integrated"] = (
        np.zeros_like(base_pose_obs) if zero_obs else base_pose_obs.copy()
    )
    # Perception overrides the server never listed (metadata can lag the model's
    # true inputs); extras are ignored server-side, so sending them is safe.
    for k, v in override_obs.items():
        if k not in payload:
            payload[k] = v
    payload["task_id"] = task_ID_one_hot(task_id)
    optional_v2 = {"robot0_joint_pos_hist", "base_traj"}
    missing = [k for k in all_keys if k not in payload and k not in optional_v2]
    if missing:
        raise KeyError(
            f"Cannot satisfy required server obs keys: {missing}. Built: {list(payload.keys())}"
        )
    return payload


def _integrate_base_deltas_base_frame(deltas: np.ndarray) -> np.ndarray:
    deltas = np.asarray(deltas, dtype=np.float64)
    pose = np.zeros(3, dtype=np.float64)
    for dx_base, dy_base, dyaw in deltas.reshape(-1, 3):
        # Dataset/export convention: per-step base deltas are already expressed in
        # the rollout start frame. Do not rotate XY by the running yaw.
        pose[0] += float(dx_base)
        pose[1] += float(dy_base)
        pose[2] += float(dyaw)
    return pose


def _base_delta_from_action_row(row: np.ndarray, rules) -> np.ndarray:
    cmd = HWCommand()
    cmd.apply_rules(np.asarray(row, dtype=np.float64), rules)
    return np.asarray(cmd.base, dtype=np.float64).reshape(3)


def dataset_base_pose_obs_at_step(
    dataset: RolloutDataset,
    initial_step: int,
) -> np.ndarray | None:
    obs = dataset.get_obs(initial_step)
    if "base_pose_integrated" not in obs:
        return None
    return np.asarray(obs["base_pose_integrated"], dtype=np.float64).reshape(-1)


def dataset_base_reset_pose_at_step(
    dataset: RolloutDataset,
    initial_step: int,
    rules,
) -> np.ndarray:
    base_obs = dataset_base_pose_obs_at_step(dataset, initial_step)
    if base_obs is not None and base_obs.size == 3:
        return base_obs.reshape(3)

    if initial_step <= 0:
        return np.zeros(3, dtype=np.float64)
    if dataset.reader is None:
        return np.zeros(3, dtype=np.float64)
    deltas = [
        _base_delta_from_action_row(dataset.reader.get_action_row(i), rules)
        for i in range(initial_step)
    ]
    return _integrate_base_deltas_base_frame(np.asarray(deltas, dtype=np.float64))


def _base_pose_obs_dim_from_metadata(metadata: dict) -> int | None:
    for container_key in ("proprio_shapes", "obs_shapes", "observation_shapes", "shape_meta"):
        container = metadata.get(container_key)
        if not isinstance(container, dict):
            continue
        for key in ("base_pose_integrated", "obs.base_pose_integrated"):
            shape = container.get(key)
            if shape is None:
                continue
            if isinstance(shape, int):
                return int(shape)
            try:
                shape_list = list(shape)
            except TypeError:
                continue
            if shape_list:
                return int(shape_list[-1])
    for key in ("base_pose_integrated_dim", "obs.base_pose_integrated_dim"):
        if key in metadata:
            return int(metadata[key])
    return None


def resolve_base_pose_obs_dim(
    *,
    metadata: dict,
    dataset_ref_obs: dict | None,
) -> int:
    if dataset_ref_obs is not None and "base_pose_integrated" in dataset_ref_obs:
        return int(np.asarray(dataset_ref_obs["base_pose_integrated"]).size)
    metadata_dim = _base_pose_obs_dim_from_metadata(metadata)
    if metadata_dim is not None and metadata_dim > 0:
        return metadata_dim
    return 3


def build_base_pose_observation(
    *,
    base_pose_obs_dim: int,
    base_pose_integrator: RolloutBasePoseIntegrator,
    base_pose_history: BasePoseHistoryWindow | None,
    odom: tuple[float, ...] | np.ndarray | None,
) -> np.ndarray:
    base_pose_3d = base_pose_integrator.update(odom)
    if base_pose_obs_dim == 3:
        return base_pose_3d
    if base_pose_history is None:
        return np.zeros(base_pose_obs_dim, dtype=np.float32)
    return base_pose_history.update(base_pose_3d)


def record_base_pose_history_sample(
    *,
    base_pose_integrator: RolloutBasePoseIntegrator,
    base_pose_history: BasePoseHistoryWindow | None,
    odom: tuple[float, ...] | np.ndarray | None,
) -> np.ndarray:
    """Record live odom into the waypoint history at rollout control cadence."""
    prev_odom_time = base_pose_integrator.last_odom_time
    odom_time = None
    if odom is not None:
        odom_arr = np.asarray(odom, dtype=np.float64).reshape(-1)
        if odom_arr.size >= 4 and np.isfinite(odom_arr[3]):
            odom_time = float(odom_arr[3])
    base_pose_3d = base_pose_integrator.update(odom)
    odom_is_new = (
        odom_time is None
        or prev_odom_time is None
        or odom_time > float(prev_odom_time)
    )
    if base_pose_history is not None and odom_is_new:
        base_pose_history.record(base_pose_3d)
    return base_pose_3d


def _relative_pose_between_odom(
    origin_odom_pose: np.ndarray,
    current_odom_pose: np.ndarray,
) -> np.ndarray:
    origin = np.asarray(origin_odom_pose, dtype=np.float64).reshape(3)
    current = np.asarray(current_odom_pose, dtype=np.float64).reshape(3)
    dx_world = current[0] - origin[0]
    dy_world = current[1] - origin[1]
    c0 = float(np.cos(origin[2]))
    s0 = float(np.sin(origin[2]))
    return np.array(
        [
            c0 * dx_world + s0 * dy_world,
            -s0 * dx_world + c0 * dy_world,
            _wrap_angle_delta(current[2] - origin[2]),
        ],
        dtype=np.float64,
    )


def _relative_pose_to_odom_goal(
    origin_odom_pose: np.ndarray,
    relative_pose: np.ndarray,
) -> np.ndarray:
    origin = np.asarray(origin_odom_pose, dtype=np.float64).reshape(3)
    rel = np.asarray(relative_pose, dtype=np.float64).reshape(3)
    c0 = float(np.cos(origin[2]))
    s0 = float(np.sin(origin[2]))
    return np.array(
        [
            origin[0] + c0 * rel[0] - s0 * rel[1],
            origin[1] + s0 * rel[0] + c0 * rel[1],
            origin[2] + rel[2],
        ],
        dtype=np.float64,
    )


def reset_base_to_dataset_pose(
    RBY1: RobotMwithBase,
    target_base_pose: np.ndarray,
    *,
    timeout_sec: float = 20.0,
    pos_tol_m: float = 0.03,
    yaw_tol_rad: float = np.deg2rad(3.0),
) -> np.ndarray:
    target = np.asarray(target_base_pose, dtype=np.float64).reshape(3)
    if not np.all(np.isfinite(target)):
        print("[reset][base] Invalid dataset base pose; leaving base where it is.")
        return np.zeros(3, dtype=np.float64)

    try:
        odom = RBY1.get_current_odometry()
    except Exception:
        odom = None
    if odom is None:
        print("[reset][base] Odometry unavailable; leaving base where it is.")
        return np.zeros(3, dtype=np.float64)

    start_odom = np.asarray(odom[:3], dtype=np.float64)
    goal = _relative_pose_to_odom_goal(start_odom, target)
    print(
        "[reset][base] Dataset target "
        f"x={target[0]:.3f} y={target[1]:.3f} "
        f"theta={np.degrees(target[2]):.1f}deg -> odom goal "
        f"x={goal[0]:.3f} y={goal[1]:.3f} theta={np.degrees(goal[2]):.1f}deg"
    )

    RBY1.ctrl.set_goal(x=float(start_odom[0]), y=float(start_odom[1]), yaw=float(start_odom[2]))
    time.sleep(0.05)
    RBY1.ctrl.set_goal(x=float(goal[0]), y=float(goal[1]), yaw=float(goal[2]))

    deadline = time.monotonic() + float(timeout_sec)
    last_pose = start_odom.copy()
    while time.monotonic() < deadline:
        odom_now = RBY1.get_current_odometry()
        if odom_now is None:
            time.sleep(0.05)
            continue
        last_pose = np.asarray(odom_now[:3], dtype=np.float64)
        pos_err = float(np.linalg.norm(last_pose[:2] - goal[:2]))
        yaw_err = abs(_wrap_angle_delta(last_pose[2] - goal[2]))
        if pos_err <= pos_tol_m and yaw_err <= yaw_tol_rad:
            print(
                "[reset][base] Reached base reset target "
                f"(pos_err={pos_err:.3f}m yaw_err={np.degrees(yaw_err):.1f}deg)."
            )
            break
        time.sleep(0.1)
    else:
        pos_err = float(np.linalg.norm(last_pose[:2] - goal[:2]))
        yaw_err = abs(_wrap_angle_delta(last_pose[2] - goal[2]))
        print(
            "[reset][base][WARNING] Timed out before target "
            f"(pos_err={pos_err:.3f}m yaw_err={np.degrees(yaw_err):.1f}deg)."
        )

    return _relative_pose_between_odom(start_odom, last_pose)


